// Package audit appends audit events inside a caller's transaction.
//
// Audit rows are part of the same transaction as the change they describe, so a
// refused or rolled-back write never leaves a trail that claims it happened, and
// a committed change is never invisible to the trail.
//
// The package deliberately depends on nothing but database/sql: identity and
// policy both write audit events, and neither may import the other. The event id
// is generated by PostgreSQL (`gen_random_uuid()`, built in since 13), which
// keeps this helper free of a UUID dependency as well.
package audit

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
)

// Record appends one audit event.
//
// metadata is typed, non-secret context (logins, roles, resource ids are
// acceptable; passwords, tokens and cookie values are not). A nil actor records
// a system action.
func Record(
	ctx context.Context,
	tx *sql.Tx,
	actorID *string,
	action string,
	resourceType string,
	resourceID *string,
	metadata map[string]any,
) error {
	payload := []byte("{}")
	if len(metadata) > 0 {
		encoded, err := json.Marshal(metadata)
		if err != nil {
			return fmt.Errorf("encoding audit metadata for %s: %w", action, err)
		}
		payload = encoded
	}
	if _, err := tx.ExecContext(
		ctx,
		`INSERT INTO platform.audit_events (id, actor_id, action, resource_type, resource_id, metadata)
		 VALUES (gen_random_uuid(), $1, $2, $3, $4, $5)`,
		actorID, action, resourceType, resourceID, string(payload),
	); err != nil {
		return fmt.Errorf("recording audit event %s: %w", action, err)
	}
	return nil
}
